const initialState = (): WorldState => ({ Vok: "nim" });

export const protocol: WorldProtocol = {
  reset(): WorldState {
    return initialState();
  },

  applyOperation(
    state: WorldState,
    operationDisplayName: string
  ):
    | { success: true; newState: WorldState }
    | { success: false; error: string } {
    if (operationDisplayName === "setVokPex") {
      return {
        success: true,
        newState: { ...state, Vok: "pex" },
      };
    }

    if (
      operationDisplayName === "resetVok" ||
      operationDisplayName === "setVokToNim"
    ) {
      if (state.Vok !== "pex") {
        return {
          success: false,
          error: "resetVok requires Vok to be in state pex",
        };
      }

      return {
        success: true,
        newState: { ...state, Vok: "nim" },
      };
    }

    return {
      success: false,
      error: `Unknown operation: ${operationDisplayName}`,
    };
  },

  getEntityState(state: WorldState, entityDisplayName: string): string {
    return state[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state: WorldState): Record<string, string> {
    return { ...state };
  },
